          },
          "statusText": {
            "type": "string",
            "description": "听书目标完成状态的短标签。",
            "sampleValue": "快到目标"
          },
          "reminderText": {
            "type": "string",
            "description": "接近听书目标时展示的提醒建议。",
            "sampleValue": "再听会儿达标"
          },
          "updatedText": {
            "type": "string",
            "description": "本周听书统计数据的更新时间文本。",
            "sampleValue": "周日 20:30 更新"
          }
        }
      }
    }
  },
  "assetCandidates": []
}

